<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$actor=$auth->requireUser();$appId=(int)($_GET['id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$appId]);if(!$app){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono aplikacji.</div>',$actor);}if(!$appAdmins->canManage((int)$actor['id'],$appId,'manage_users')){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Nie masz uprawnień do użytkowników tej aplikacji.</div>',$actor);}
$applyRole=static function(int$userId,int$roleId,string$action)use($db,$audit,$actor,$appId):void{$role=$db->one('SELECT id,name FROM app_roles WHERE id=? AND application_id=?',[$roleId,$appId]);if(!$role)return;if($action==='assign_role')$db->execute('INSERT IGNORE INTO app_user_roles(application_id,user_id,app_role_id,created_by) VALUES(?,?,?,?)',[$appId,$userId,$roleId,(int)$actor['id']]);else$db->execute('DELETE FROM app_user_roles WHERE application_id=? AND user_id=? AND app_role_id=?',[$appId,$userId,$roleId]);$audit->write('application.user_role.'.($action==='assign_role'?'assigned':'removed'),'success',(int)$actor['id'],$userId,$appId,null,['role'=>$role['name']]);};
if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'');$roleId=(int)($_POST['app_role_id']??0);$userIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['user_ids']??[])),static fn(int$v):bool=>$v>0)));if($userIds===[]){$single=(int)($_POST['user_id']??0);if($single>0)$userIds=[$single];}foreach($userIds as$userId){if($action==='grant')$access->grantUser($appId,$userId,(int)$actor['id']);elseif($action==='revoke')$access->revokeUser($appId,$userId,(int)$actor['id']);elseif(in_array($action,['assign_role','remove_role'],true)&&$roleId>0){if(!$appAdmins->canManage((int)$actor['id'],$appId,'manage_roles'))continue;$applyRole($userId,$roleId,$action);}}Web::redirect('/admin/applications/'.$appId.'/users'.(!empty($_GET['q'])?'?q='.rawurlencode((string)$_GET['q']):''));}
$q=trim((string)($_GET['q']??''));$params=[$appId];$sql='SELECT u.id,u.name,u.email,u.enabled,au.enabled AS direct_enabled,au.created_at,creator.email AS creator_email FROM users u LEFT JOIN application_users au ON au.user_id=u.id AND au.application_id=? LEFT JOIN users creator ON creator.id=au.created_by';if($q!==''){$sql.=' WHERE u.name LIKE ? OR u.email LIKE ?';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}$sql.=' ORDER BY u.name LIMIT 200';$users=$db->all($sql,$params);$roles=$db->all('SELECT id,name FROM app_roles WHERE application_id=? ORDER BY name',[$appId]);$roleOptions='<option value="">— wybierz rolę —</option>';foreach($roles as$role)$roleOptions.='<option value="'.(int)$role['id'].'">'.Web::e($role['name']).'</option>';$canRoles=$appAdmins->canManage((int)$actor['id'],$appId,'manage_roles');$rows='';
foreach($users as$u){$uid=(int)$u['id'];$has=$access->hasAccess($uid,$app);$userRoles=$access->rolesForUser($uid,$appId);$direct=$u['direct_enabled']===null?'Dziedziczony / brak wpisu':((bool)$u['direct_enabled']?'Jawnie nadany':'Jawnie zablokowany');$rows.='<tr><td><input type="checkbox" name="user_ids[]" value="'.$uid.'" form="bulkForm"></td><td><strong>'.Web::e($u['name']).'</strong></td><td>'.Web::e($u['email']).'</td><td>'.((bool)$u['enabled']?'Aktywny':'Wyłączony').'</td><td><span class="badge '.($has?'ok':'muted').'">'.($has?'Tak':'Nie').'</span><div class="muted">'.Web::e($direct).'</div></td><td>'.Web::e(implode(', ',$userRoles)?:'—').'</td><td>'.Web::e($u['created_at']?:'—').'</td><td>'.Web::e($u['creator_email']?:'—').'</td><td><form method="post" class="inline"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.$uid.'"><button name="action" value="'.($has?'revoke':'grant').'">'.($has?'Odbierz':'Nadaj').' dostęp</button></form>'.($canRoles&&$roles!==[]?'<form method="post" class="inline"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.$uid.'"><select name="app_role_id" required>'.$roleOptions.'</select><button name="action" value="assign_role">+ rola</button><button name="action" value="remove_role">− rola</button></form>':'').'</td></tr>';}
if($rows==='')$rows='<tr><td colspan="9" class="empty">Brak użytkowników.</td></tr>';$bulkRole=$canRoles?'<option value="assign_role">Przypisz rolę</option><option value="remove_role">Usuń rolę</option>':'';$content='<div class="page-head"><div><h1>Użytkownicy — '.Web::e($app['name']).'</h1><p>Jawne nadania i blokady mają pierwszeństwo nad dostępem dziedziczonym.</p></div><a class="button" href="/admin/applications/'.$appId.'">Wróć</a></div><section class="card"><form method="get" class="toolbar"><input name="q" value="'.Web::e($q).'" placeholder="Szukaj"><button>Szukaj</button></form></section><section class="card"><form method="post" id="bulkForm" class="toolbar"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><select name="action"><option value="grant">Nadaj dostęp</option><option value="revoke">Odbierz dostęp</option>'.$bulkRole.'</select>'.($canRoles?'<select name="app_role_id">'.$roleOptions.'</select>':'').'<button class="primary">Wykonaj</button></form></section><div class="table-wrap"><table><thead><tr><th></th><th>Użytkownik</th><th>E-mail</th><th>Status</th><th>Dostęp</th><th>Role</th><th>Data</th><th>Nadał</th><th>Akcje</th></tr></thead><tbody>'.$rows.'</tbody></table></div>';Web::page('Użytkownicy aplikacji',$content,$actor);
